const ddl = [
    "DROP VIEW IF EXISTS vw_media_curso",
    "DROP TABLE IF EXISTS matriculas",
    "DROP TABLE IF EXISTS alunos",
    "DROP TABLE IF EXISTS cursos",

    "CREATE TABLE cursos (curso_id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(60) NOT NULL, carga_horaria INT)",
    "CREATE TABLE alunos (aluno_id INT AUTO_INCREMENT PRIMARY KEY, nome VARCHAR(60) NOT NULL, cidade VARCHAR(40), ano_ingresso INT)",
    "CREATE TABLE matriculas (matricula_id INT AUTO_INCREMENT PRIMARY KEY, aluno_id INT NOT NULL, curso_id INT NOT NULL, semestre VARCHAR(7), nota DECIMAL(4,2), FOREIGN KEY (aluno_id) REFERENCES alunos(aluno_id), FOREIGN KEY (curso_id) REFERENCES cursos(curso_id))",

    "INSERT INTO cursos (nome, carga_horaria) VALUES ('Redes de Computadores',80),('Computacao em Nuvem',60),('Banco de Dados',80),('Seguranca da Informacao',40)",
    "INSERT INTO alunos (nome, cidade, ano_ingresso) VALUES ('Ana Souza','Dourados',2023),('Bruno Lima','Dourados',2024),('Carla Dias','Ponta Pora',2023),('Diego Alves','Campo Grande',2025),('Elisa Rocha','Dourados',2025),('Felipe Nunes','Ponta Pora',2024),('Gabriela Melo','Campo Grande',2026),('Heitor Pinto','Dourados',2026)",
