];
// Heitor Pinto (aluno 8) fica sem matricula de proposito: serve para o LEFT JOIN.
// A lista viaja DENTRO da mensagem; o no "proximo comando" devolve um por vez,
// so depois que o anterior terminou - senao a ordem do DDL nao e garantida.
msg.lista = ddl;
msg.i = 0;
msg.topic = ddl[0];
msg.payload = [];
return msg;

// Saida 1: proximo comando (volta para o no MySQL).
// Saida 2: acabou -> resumo para o debug.
msg.i = (msg.i || 0) + 1;
if (msg.i < msg.lista.length) {
    msg.topic = msg.lista[msg.i];
    msg.payload = [];
    return [msg, null];
}
return [null, { payload: msg.lista.length + " comandos executados, na ordem." }];

